// 人物经历。life 是三个人生节点，dims 是每个节点体现的维度序号，结果页用它和用户同一维度的选择配对。
const stories={
 '苏轼':{text:'苏轼一生辗转多地，除了文学创作，也留下书法与绘画作品。黄州时期，他写下了《赤壁赋》等作品。',life:['二十出头与弟弟苏辙同科进士及第，文名传遍京城。','因“乌台诗案”下狱，后贬到黄州，在那里自号东坡居士。','晚年又被贬到惠州和儋州，在海南仍然讲学著述。'],dims:[4,7,2]},
 '李白':{text:'李白青年时期离开蜀地，游历各地。他的旅行经历与山水诗作，让后人看到一位在路上的诗人。',life:['二十多岁辞亲出蜀，开始漫游各地。','天宝初年奉诏入长安，供奉翰林，不久离开朝廷。','安史之乱中因入永王幕府获罪，流放夜郎，途中遇赦。'],dims:[0,3,7]},
 '杜甫':{text:'安史之乱前后，杜甫经历了战乱和辗转。他在《三吏》《三别》等诗作中描写了战争中的百姓。',life:['青年时漫游各地，与李白结下交情。','安史之乱中陷于长安，脱身后投奔唐肃宗，任左拾遗。','晚年寄居成都草堂，又漂泊湘江，病逝于舟中。'],dims:[6,7,5]},
 '李清照':{text:'李清照的词作记录了生活与时代的变化。她也与丈夫赵明诚共同研究金石文物，并参与整理相关资料。',life:['少女时已有词名，婚后与赵明诚一起搜集金石文物。','靖康之变后南渡，丈夫病逝，藏品也大多散失。','晚年为《金石录》写后序，词风转为沉郁。'],dims:[5,7,2]},
 '司马迁':{text:'司马迁继承父亲记述历史的志愿，撰写《史记》，以纪传体记录从传说时代到汉代的历史。',life:['青年时游历各地，实地考察史迹和传说。','因替李陵辩解获罪，受了宫刑。','忍辱继续写作，完成了纪传体通史《史记》。'],dims:[1,7,5]},
 '诸葛亮':{text:'诸葛亮辅佐刘备，提出有关天下形势的谋划。蜀汉建立后，他参与政务与军事事务。',life:['隐居隆中，刘备三顾茅庐后出山。','促成孙刘联合抗曹，后来辅佐刘备建立蜀汉。','任蜀汉丞相，多次北伐，病逝于五丈原军中。'],dims:[6,1,7]},
 '孔子':{text:'孔子长期从事教育，也曾周游列国。他与弟子及当时人物的言行，被后人整理在《论语》等文献中。',life:['少年贫贱，做过管理仓库和牲畜的小吏。','在鲁国为官后离开，带着弟子周游列国十余年。','晚年回到鲁国，专心教学和整理典籍。'],dims:[4,7,2]},
 '郑和':{text:'明代的郑和率领船队多次远航，航行范围包括东南亚、印度洋沿岸和东非等地。',life:['本姓马，云南人，入宫后得明成祖赐姓郑。','1405 年起率庞大船队七下西洋。','船队到过东南亚、印度洋沿岸和东非。'],dims:[6,3,0]},
 '徐霞客':{text:'徐霞客长期旅行考察，在游记中记录了山川、道路和沿途见闻。他的旅行记录后来整理为《徐霞客游记》。',life:['青年时不走科举之路，立志游历天下。','三十多年间走遍大半个中国，常常亲身探查山川洞穴。','留下的日记后来整理成《徐霞客游记》。'],dims:[6,0,5]},
 '李时珍':{text:'李时珍查阅本草文献，结合对药物的考察，编成《本草纲目》，整理了大量药物知识。',life:['乡试三次不中，转而跟随父亲学医。','行医之余走访各地，亲自采药、向百姓求教。','历时近三十年，三易其稿，写成《本草纲目》。'],dims:[6,0,5]},
 '曹雪芹':{text:'曹雪芹是清代小说家，《红楼梦》描绘了人物关系和家族生活，留下了丰富的文学人物形象。',life:['出身江宁织造曹家，少年时家境显赫。','家族败落后移居北京西郊，生活困顿。','在贫困中“批阅十载”，写下《红楼梦》。'],dims:[1,6,5]},
 '鲁迅':{text:'鲁迅从事小说、杂文和翻译等写作。《狂人日记》和《阿Q正传》是他的代表作品。',life:['留学日本学医，后来弃医从文。','1918 年发表《狂人日记》，这是现代白话小说的开山之作。','晚年定居上海，写下大量杂文。'],dims:[0,7,1]},
 '达·芬奇':{text:'达·芬奇既创作绘画，也留下了解剖、机械和自然观察等方面的手稿。他的兴趣跨越艺术与研究。',life:['少年时在佛罗伦萨韦罗基奥的工坊学艺。','在米兰宫廷任职期间，画了《最后的晚餐》。','晚年应法国国王之邀移居法国，在那里去世。'],dims:[5,4,0]},
 '居里夫人':{text:'居里夫人研究放射性，参与发现钋和镭，并先后获得诺贝尔物理学奖和化学奖。',life:['从波兰到巴黎求学，生活清苦。','与丈夫皮埃尔发现钋和镭，1903 年共获诺贝尔物理学奖。','1911 年又获诺贝尔化学奖，是两次获奖的第一人。'],dims:[6,5,1]},
 '爱因斯坦':{text:'爱因斯坦提出相对论，并因对理论物理学的贡献、尤其是对光电效应的解释获得诺贝尔物理学奖。',life:['在瑞士专利局工作时，1905 年发表多篇划时代的论文。','1921 年因解释光电效应获诺贝尔物理学奖。','1933 年后定居美国，在普林斯顿继续研究。'],dims:[4,1,5]},
 '达尔文':{text:'达尔文随“小猎犬号”远航，观察和收集自然材料。此后的研究促成了他对物种演化的论述。',life:['二十出头登上贝格尔号，随船环球考察约五年。','回国后花了二十多年积累证据、反复思考。','1859 年出版《物种起源》，提出自然选择学说。'],dims:[0,5,1]},
 '莎士比亚':{text:'莎士比亚在伦敦戏剧界工作，创作戏剧和诗歌。《哈姆雷特》《罗密欧与朱丽叶》等作品流传至今。',life:['生于斯特拉特福，后来到伦敦做演员和编剧。','参与环球剧场的经营，作品常在那里上演。','留下《哈姆雷特》《罗密欧与朱丽叶》等三十多部戏剧。'],dims:[6,2,4]},
 '简·奥斯汀':{text:'简·奥斯汀创作了《傲慢与偏见》等小说，以人物关系和日常生活为重要的叙事内容。',life:['生长在牧师家庭，少女时就开始写小说自娱。','匿名出版《理智与情感》《傲慢与偏见》。','四十一岁病逝，作者身份在她去世后才公开。'],dims:[5,2,6]},
 '南丁格尔':{text:'南丁格尔在克里米亚战争期间参与护理工作，后来推动护理教育，并利用统计图表说明卫生问题。',life:['出身富裕家庭，不顾家人反对坚持学习护理。','克里米亚战争时率护士赴前线，整顿战地医院。','用统计图表推动医疗改革，创办了护士学校。'],dims:[7,3,1]},
 '梵高':{text:'梵高在艺术生涯中创作了大量绘画与素描，也在写给亲友的信中谈论自己的创作。',life:['做过画商和传教士，二十七岁才决心成为画家。','在法国南部阿尔画下《向日葵》等名作。','1890 年去世，生前很少得到认可。'],dims:[0,4,5]},
 '武则天':{text:'她从唐高宗的皇后走到称帝，建立武周，是中国历史上唯一得到正统承认的女皇帝。',life:['十四岁入宫，后来成为唐高宗的皇后。','高宗在世时已参与朝政，690 年称帝，改国号为周。','重视科举选才；晚年神龙政变后退位。'],dims:[7,6,4]},
 '曹操':{text:'曹操在东汉末年统一北方，既是政治家、军事家，也留下了《短歌行》《龟虽寿》等诗作。',life:['年轻时举孝廉，后来起兵讨伐董卓。','迎汉献帝到许都，推行屯田，在官渡战胜袁绍。','赤壁失利后经营北方，也写下《观沧海》等诗。'],dims:[6,3,5]},
 '岳飞':{text:'岳飞是南宋抗金将领，治军严明，后来遭秦桧等人陷害而死。',life:['出身农家，青年从军抗金。','率岳家军屡败金军，郾城之战是著名的胜仗。','被召回后以“莫须有”的罪名遇害，后来得到平反。'],dims:[6,3,7]},
 '陶渊明':{text:'陶渊明辞去彭泽县令后归隐田园，写下《归去来兮辞》和许多田园诗。',life:['几次出仕，又几次辞官。','任彭泽县令八十多天后辞官，从此归隐。','躬耕田园，写下《归去来兮辞》和《桃花源记》。'],dims:[3,6,2]},
 '庄子':{text:'庄子是战国时期的思想家，《庄子》一书以寓言和奇想著称，《逍遥游》是其中的名篇。',life:['战国时宋国人，做过管理漆园的小吏。','相传楚王请他为相，他宁愿像龟一样曳尾于泥中。','《庄子》一书以寓言谈逍遥与齐物。'],dims:[2,6,4]},
 '屈原':{text:'屈原是战国时期楚国的政治家和诗人，遭到放逐后写下《离骚》等作品。',life:['楚怀王时任左徒，主张联齐抗秦。','遭谗言被疏远、流放，写下《离骚》。','郢都被攻破后，投汨罗江而死。'],dims:[6,4,7]},
 '林徽因':{text:'林徽因是建筑学家和文学家，参与中国古建筑考察和国徽方案设计，也创作诗歌和小说。',life:['留学美国，在宾夕法尼亚大学学习美术和建筑。','与梁思成跋涉各地，考察测绘中国古建筑。','参与了国徽和人民英雄纪念碑的设计工作。'],dims:[5,0,4]},
 '海伦·凯勒':{text:'海伦·凯勒幼年失明失聪，在老师安妮·莎莉文的帮助下学会读写，后来成为作家和社会活动家。',life:['一岁多时因病失明失聪。','老师安妮·莎莉文在她手心拼写，教会她语言。','毕业于拉德克利夫学院，一生写作、演讲，为残障人士奔走。'],dims:[1,5,2]},
 '贝多芬':{text:'贝多芬是德国作曲家，听力逐渐衰退后仍继续创作，留下了九部交响曲等作品。',life:['生于波恩，到维也纳后曾向海顿学习。','二十多岁起听力衰退，写下《海利根施塔特遗书》。','几乎全聋时完成了《第九交响曲》。'],dims:[6,7,5]},
 '牛顿':{text:'牛顿是英国物理学家和数学家，提出运动定律和万有引力定律，也是微积分的创立者之一。',life:['1665 年瘟疫时回到家乡，深入思考光和引力。','1687 年出版《自然哲学的数学原理》。','后来担任皇家造币厂主管和皇家学会会长。'],dims:[2,1,3]},
 '范蠡':{text:'范蠡辅佐越王勾践灭吴之后，没有留在朝中，而是离开越国，到齐地和陶地经商。据《史记》记载，他几次积累千金，又分给贫穷的朋友和亲族。',life:['越国战败后，陪越王勾践到吴国为质。','辅佐勾践复国灭吴，成为上将军。','功成后离开越国经商，人称陶朱公。'],dims:[7,1,5]},
 '张良':{text:'张良是刘邦的重要谋士，在楚汉相争中多次出谋划策。汉朝建立后，他逐渐退出朝政，以修道养生自处。',life:['年轻时在博浪沙派力士行刺秦始皇，未能成功。','成为刘邦的谋士，在鸿门宴等关头多次出谋划策。','汉朝建立后受封留侯，渐渐淡出朝政。'],dims:[4,1,6]},
 '王维':{text:'王维兼通诗、画和音乐，山水田园诗尤为后人称道。他晚年信佛，在蓝田辋川经营别业，常在山水间往来。',life:['年少成名，开元年间考中进士。','安史之乱中被迫接受伪职，乱后获得宽宥。','晚年居于辋川别业，与友人写诗唱和，结成《辋川集》。'],dims:[4,6,2]},
 '王阳明':{text:'王阳明被贬到贵州龙场时，在困境中悟出了自己的学说，后来提出“知行合一”。他也是一位能带兵的文官，曾平定宁王之乱。',life:['考中进士后入朝为官。','得罪宦官刘瑾被贬贵州龙场，在那里悟道。','平定宁王之乱，晚年讲学，提倡“致良知”。'],dims:[6,7,2]},
 '唐伯虎':{text:'唐寅，字伯虎，年轻时才名很盛，后来因科场案断了仕途。他回到苏州，靠卖画为生，在桃花坞筑屋而居，诗文书画都留下了作品。',life:['二十九岁乡试第一，人称唐解元。','第二年进京会试，受科场案牵连，断了仕途。','回到苏州，在桃花坞筑屋，以卖画为生。'],dims:[4,6,3]},
 '刘邦':{text:'刘邦出身沛县平民，做过亭长，秦末起兵，在楚汉相争中战胜项羽，建立汉朝。他自己也说过，能取天下靠的是善用张良、萧何、韩信这样的人才。',life:['出身沛县平民，做过泗水亭长。','秦末起兵，先入关中，与百姓约法三章。','垓下一战击败项羽，建立汉朝。'],dims:[4,2,6]},
 '苏格拉底':{text:'苏格拉底常在雅典的公共场所与人讨论什么是正义、什么是美德。他本人没有留下著作，他的思想主要见于柏拉图等学生的记述。',life:['生于雅典，曾作为重装步兵上过战场。','常在街头广场与人对话，用追问检验各种说法。','被控不敬神、败坏青年，判处死刑后饮下毒堇汁。'],dims:[6,2,7]},
 '富兰克林':{text:'富兰克林从印刷学徒做起，后来办报、研究电学、发明避雷针，也从事外交。他还参与起草了美国《独立宣言》。',life:['十七岁离家到费城，从印刷工做起。','做过风筝实验研究闪电，发明了避雷针。','参与起草《独立宣言》，又出使法国争取支持。'],dims:[6,5,2]},
 '上官婉儿':{text:'上官婉儿幼年随母亲没入宫中，因文才得到武则天重用，掌管诏命。唐中宗时，她又主持宫廷诗会的评选，在政局变动中经历了几朝风云。',life:['祖父获罪后，幼年随母亲没入掖庭。','因才华得到武则天重用，掌管诏命。','唐中宗时主持诗坛，最终在唐隆政变中被杀。'],dims:[1,6,7]},
 '杨贵妃':{text:'杨玉环是唐玄宗的贵妃，史书记载她善歌舞、通晓音律。她的一生随安史之乱结束于马嵬驿，白居易的《长恨歌》让这段故事流传至今。',life:['本是寿王妃，后来入宫，被册封为贵妃。','善歌舞、通音律，尤以《霓裳羽衣舞》闻名。','安史之乱中，在马嵬驿被赐死。'],dims:[7,4,1]}
};
